  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --surface: #ffffff;
      --surface-alt: #f8fafc;
      --text: #122033;
      --muted: #52627a;
      --border: #d7e0ec;
      --accent: #3856ff;
      --accent-soft: #e9efff;
      --shadow: 0 24px 60px rgba(18, 32, 51, 0.12);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, #e7edff 0, transparent 28%),
        radial-gradient(circle at top right, #f6eaff 0, transparent 22%),
        var(--bg);
      color: var(--text);
      line-height: 1.6;
    }

