    .question[aria-expanded="true"] .question-icon {
      transform: rotate(45deg);
    }

    .details {
      padding: 0 1.5rem 1.25rem;
      color: var(--muted);
    }

    .details p {
      margin: 0.75rem 0 0;
    }

    .details ul {
      margin: 0.75rem 0 0;
      padding-left: 1.25rem;
    }

    .details li + li {
      margin-top: 0.35rem;
